<script lang="ts" module>import type {RxColor} from '$lib/registry/lib/color';export interface CodeProps{code:string;language?:string;filename?:string;color?:RxColor;variant?:'default'|'glow'|'gradient-border'|'minimal'|'terminal'|'window';theme?:'auto'|'light'|'dark';copyable?:boolean;lineNumbers?:boolean;highlightLines?:number[];wrap?:boolean;maxHeight?:string;onCopy?:(code:string)=>void}</script>
<script lang="ts">import {browser} from '$app/environment';import{onDestroy}from'svelte';import {styleColor} from '$lib/registry/lib/color';import type {CodeToken} from './highlight';let{code,language='text',filename,color,variant='default',theme='auto',copyable=false,lineNumbers=false,highlightLines=[],wrap=false,maxHeight,onCopy}:CodeProps=$props();let status=$state('');let tokens=$state<CodeToken[][]>();let statusTimer:ReturnType<typeof setTimeout>|undefined;const lines=$derived(code.split('\n'));$effect(()=>{const value=code,lang=language,mode=theme;if(!browser)return;let alive=true;import('./highlight').then(async({highlightCode})=>{const light=mode==='light'||(mode==='auto'&&matchMedia('(prefers-color-scheme: light)').matches);const result=await highlightCode(value,lang,light);if(alive)tokens=result});return()=>{alive=false}});async function copy(){if(statusTimer)clearTimeout(statusTimer);try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(code);else{const area=document.createElement('textarea');area.value=code;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();if(!document.execCommand('copy'))throw new Error('Copy failed');area.remove()}status='Copied';onCopy?.(code)}catch{status='Could not copy'}statusTimer=setTimeout(()=>{status='';statusTimer=undefined},1800)}function spotlight(node:HTMLElement){const move=(event:PointerEvent)=>{const rect=node.getBoundingClientRect();node.style.setProperty('--rx-code-gx',`${event.clientX-rect.left}px`);node.style.setProperty('--rx-code-gy',`${event.clientY-rect.top}px`);node.style.setProperty('--rx-code-glow','1')};const leave=()=>node.style.setProperty('--rx-code-glow','0');node.addEventListener('pointermove',move,{passive:true});node.addEventListener('pointerleave',leave);return()=>{node.removeEventListener('pointermove',move);node.removeEventListener('pointerleave',leave)}}onDestroy(()=>{if(statusTimer)clearTimeout(statusTimer)})</script>
<figure class="rx-code rx-code--{variant}" data-theme={theme} style={`${styleColor(color)??'--rx-color:var(--rx-primary)'};${maxHeight?`--rx-code-max:${maxHeight}`:''}`} {@attach spotlight}><span class="rx-code__frame" aria-hidden="true"></span><span class="rx-code__spot" aria-hidden="true"></span>{#if filename||copyable||variant==='terminal'||variant==='window'}<figcaption>{#if variant==='window'}<span class="rx-code__lights" aria-hidden="true">● ● ●</span>{/if}<span class="rx-code__language">{filename??(variant==='terminal'?'Terminal':language)}</span>{#if copyable}<button class:copied={status==='Copied'} type="button" aria-label="Copy" onclick={copy}>{status==='Copied'?'Copied':'Copy'}</button>{/if}</figcaption>{/if}<pre class:wrap aria-label={filename?`Code in ${filename}`:'Code sample'}><code>{#each (tokens??lines.map(line=>[{content:line}])) as line,i}<span class:highlight={highlightLines.includes(i+1)}><i aria-hidden="true">{lineNumbers?i+1:''}</i><b>{#each line as token}<em style:--rx-token-color={'color' in token?String(token.color):undefined}>{token.content}</em>{/each}</b>{#if i<(tokens?.length??lines.length)-1}{'\n'}{/if}</span>{/each}{#if variant==='terminal'}<span class="rx-code__caret" aria-hidden="true"></span>{/if}</code></pre><span class="rx-code__status" aria-live="polite">{status}</span></figure>
<style>
