	.rx-code--minimal{--rx-code-bg:transparent;--rx-code-fg:rgb(var(--rx-text));border:0;border-radius:0}.rx-code--minimal figcaption{border:0}.rx-code--minimal .rx-code__language{transition:opacity 180ms}.rx-code--minimal button{position:absolute;top:6px;right:8px;width:26px;height:26px;padding:0;opacity:0;backdrop-filter:blur(6px);transition:opacity 180ms,background 160ms,color 160ms,transform 160ms}.rx-code--minimal:hover .rx-code__language{opacity:0}.rx-code--minimal:hover button,.rx-code--minimal button:focus-visible,.rx-code--minimal button.copied{opacity:1}.rx-code--glow{border-color:rgb(var(--rx-color)/.3)}.rx-code--glow .rx-code__spot{opacity:var(--rx-code-glow,0)}.rx-code--gradient-border{border-color:transparent}.rx-code--gradient-border:before{content:"";position:absolute;inset:1px;z-index:1;border-radius:calc(var(--rx-radius) - 1px);background:var(--rx-code-bg);pointer-events:none}.rx-code--gradient-border .rx-code__frame{display:block;padding:1px;background:conic-gradient(from var(--rx-code-angle),rgb(var(--rx-color)),hsl(from rgb(var(--rx-color)) calc(h + 50) s l),hsl(from rgb(var(--rx-color)) calc(h + 115) s l),rgb(var(--rx-color)));animation:rx-code-frame 6s linear infinite}.rx-code--terminal figcaption::before{content:'$';color:color-mix(in srgb,rgb(var(--rx-color)) 45%,var(--rx-code-fg));font-weight:800}.rx-code__caret{display:inline-block;width:8px;height:1.05em;margin-left:2px;vertical-align:text-bottom;background:rgb(var(--rx-color));animation:rx-code-caret 1s steps(2,start) infinite}.rx-code__lights{color:color-mix(in srgb,rgb(var(--rx-color)) 45%,var(--rx-code-fg));letter-spacing:.2rem}.rx-code--window:hover{transform:rotateX(6deg) rotateY(-5deg) translateZ(14px);box-shadow:0 6px 12px rgb(var(--rx-shadow)/.4),0 26px 50px rgb(var(--rx-shadow)/.5),0 60px 110px rgb(var(--rx-shadow)/.4)}
	@property --rx-code-angle{syntax:"<angle>";initial-value:0deg;inherits:false}@keyframes rx-code-frame{to{--rx-code-angle:360deg}}@keyframes rx-code-caret{0%,50%{opacity:1}50.01%,100%{opacity:0}}@media(prefers-reduced-motion:reduce){.rx-code,.rx-code :global(*){transition:none!important}.rx-code--gradient-border .rx-code__frame,.rx-code__caret{animation:none}.rx-code__caret{opacity:1}.rx-code--window:hover{transform:none}}
</style>
